property.code:
/* The lists of the page content (view, WYSIWYG editors, PDF export), ordered or not, at any level: the markers aligned
   to the left of the list, the text of the items, with all their paragraphs, indented. The markers follow the type of
   the list chosen in the editor ("1.", "a)", "\25E6"...) and its start. The lists with a class (e.g. trees) and the
   lists of the table of contents and of the menus keep their own style. */
:is(#xwikicontent, .cke_editable) :is(ol, ul):not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) {
  /* The markers are drawn below; the type of the list (e.g. letters) is for the editors and the other skins. */
  list-style-type: none !important;
  padding-left: 1.25cm;
}
:is(#xwikicontent, .cke_editable) :is(ol, ul):not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) > li {
  position: relative;
}
:is(#xwikicontent, .cke_editable) :is(ol, ul):not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) > li::before {
  position: absolute;
  left: -1.25cm;
}
:is(#xwikicontent, .cke_editable) ul:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) > li::before {
  content: "\2022";
}
:is(#xwikicontent, .cke_editable) :is(ol, ul) ul:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) > li::before {
  content: "\25E6";
}
:is(#xwikicontent, .cke_editable) :is(ol, ul) :is(ol, ul) ul:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) > li::before {
  content: "\25AA";
}
:is(#xwikicontent, .cke_editable) ul:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="disc"] > li::before {
  content: "\2022";
}
:is(#xwikicontent, .cke_editable) ul:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="circle"] > li::before {
  content: "\25E6";
}
:is(#xwikicontent, .cke_editable) ul:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="square"] > li::before {
  content: "\25AA";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *) > li::before {
  content: counter(list-item) ".";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="decimal-leading-zero"] > li::before {
  content: counter(list-item, decimal-leading-zero) ".";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="lower-alpha"] > li::before {
  content: counter(list-item, lower-alpha) ".";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="upper-alpha"] > li::before {
  content: counter(list-item, upper-alpha) ".";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="lower-roman"] > li::before {
  content: counter(list-item, lower-roman) ".";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="upper-roman"] > li::before {
  content: counter(list-item, upper-roman) ".";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="gkh-decimal-parenthesis"] > li::before {
  content: counter(list-item) ")";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="gkh-lower-alpha-parenthesis"] > li::before {
  content: counter(list-item, lower-alpha) ")";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="gkh-upper-alpha-parenthesis"] > li::before {
  content: counter(list-item, upper-alpha) ")";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="gkh-lower-roman-parenthesis"] > li::before {
  content: counter(list-item, lower-roman) ")";
}
:is(#xwikicontent, .cke_editable) ol:not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="gkh-upper-roman-parenthesis"] > li::before {
  content: counter(list-item, upper-roman) ")";
}
:is(#xwikicontent, .cke_editable) :is(ol, ul):not([class]):not(:is(.wikitoc, .menu-horizontal, .menu-vertical) *)[style*="list-style-type: none"] > li::before {
  content: none;
}
